def solve(inputs: dict) -> float:
    import math

    M = inputs.get('matrix', [[9, 26], [13, 16]])
    exponent = inputs.get('exponent', 37)
    modulus = inputs.get('modulus', 370583)

    def matrix_mult(A, B, mod):
        n = len(A)
        C = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % mod
        return C

    def matrix_pow(M, exp, mod):
        n = len(M)
        # Identity matrix
        result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
        base = [row[:] for row in M]

        while exp > 0:
            if exp % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            exp //= 2

        return result

    result = matrix_pow(M, exponent, modulus)

    # Sum all entries
    total = sum(sum(row) for row in result) % modulus

    return float(total)

